import { PROFILE_ACTIONS } from './actions'

const reducer = (state = PROFILE_ACTIONS, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case PROFILE_ACTIONS.UPDATE_PHONE_NUMBER:
    case PROFILE_ACTIONS.UPDATE_PROFILE:
    case PROFILE_ACTIONS.RESEND_OTP:
    case PROFILE_ACTIONS.UPDATE_AGENT_PHONE_NO:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
