import { formatNPWP } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'

export const PROFILE_FIELD_TYPE = {
  DETAIL_ROW: 'detailRow',
  ADDRESS: 'address',
  EMAIL: 'email',
  ROW_WITH_STATUS: 'rowWithStatus'
}

export const getIndividualProfileFields = ({
  agentDetails,
  agentAddress,
  isStaffAgent,
  isGojekDriver,
}) => {
  const fields = [
    {
      type: PROFILE_FIELD_TYPE.DETAIL_ROW,
      id: 'mitraId',
      title: LANG_STRINGS.mitraId,
      value: agentDetails.agent_code,
    },
    {
      type: PROFILE_FIELD_TYPE.DETAIL_ROW,
      id: 'name',
      title: LANG_STRINGS.enterNameAsInKtp,
      value: agentDetails.name,
      isEditable: true,
      isValidate: agentDetails.is_ktp_verified,
    },
    {
      type: PROFILE_FIELD_TYPE.DETAIL_ROW,
      id: 'phone_no',
      title: LANG_STRINGS.phoneNo,
      value: agentDetails.phone_no,
      isEditable: true,
    },
    {
      type: PROFILE_FIELD_TYPE.ADDRESS,
      id: 'address',
      title: LANG_STRINGS.shippingAddress,
      value: agentAddress
    },
    {
      type: PROFILE_FIELD_TYPE.EMAIL,
      id: 'email',
      title: LANG_STRINGS.emailAddress,
      value: agentDetails.email,
      isEditable: true,
      isValidate: agentDetails.is_email_verified,
    },
    {
      type: PROFILE_FIELD_TYPE.ROW_WITH_STATUS,
      id: 'ktp',
      title: LANG_STRINGS.ktpNumber,
      value: agentDetails.ktp_no,
      placeholder: LANG_STRINGS.notCompletedKTPNumberData,
      isValidate: agentDetails.is_ktp_verified,
      doc: {
        status: agentDetails.ktp_document?.status,
        reject_reason: agentDetails.ktp_document?.reject_reason
      }
    },
    {
      type: PROFILE_FIELD_TYPE.ROW_WITH_STATUS,
      id: 'npwp',
      title: LANG_STRINGS.npwpNumber,
      value: formatNPWP(agentDetails.npwp_no),
      placeholder: LANG_STRINGS.notCompletedNPWPData,
      isValidate: agentDetails.is_npwp_verified,
      doc: {
        status: agentDetails.npwp_document?.status,
        reject_reason: agentDetails.npwp_document?.reject_reason
      }
    }
  ]
  if (isStaffAgent) return fields.filter((field) => field.id !== 'address')
  if (isGojekDriver) return fields.filter((field) => field.id !== 'npwp')
  return fields
}

