import { useCallback, useRef, useState, useEffect, forwardRef, useImperativeHandle } from 'react'
import { useHistory } from 'react-router'
import { useResetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Button } from '../../../../../../components'
import EditProfileDetails from '../../../components/EditProfileDetails'
import CircularLoader from '../../../../../../components/CircularLoader'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { setToLocalStorage } from '../../../../../../helpers/localstorage'
import { typeValid } from '../../../../../../helpers/validations'
import { LANG_STRINGS } from '../../../../../../lang'
import { useUpdateAgentPhoneNo, useUpdateProfile } from '../../../state/MyProfile/hooks/useMyProfileContext'
import {
  getCorporatePicNameDetailsForm,
  getEmailDetailsForm,
  getKTPDetailsForm,
  getNameDetailsForm,
  getNIBDetailsForm,
  getNPWPDetailsForm,
  getPhoneNoDetailsForm,
  PHONE_NUMBER_DATA,
} from '../../../constants'
import { EditProfileFieldStyle } from './index.style'

function EditProfileFieldContainer ({
  type, status, data = {}, setPopUpBeforeSubmit, setBottomSheetStatus,
  setUpdateNeeded, agentDetails
}, parentRef) {
  const history = useHistory()
  const that = useRef({ ...data })
  const editProfileRef = useRef()

  const [formData, setFormData] = useState(null)
  const [btnEnable, setBtnEnable] = useState(false)

  const [{ UPDATE_PROFILE_LOADER, UPDATE_AGENT_PHONE_NO_LOADER }] = useLoaderContextValue()

  const { resetError } = useResetError()
  const [{ updateProfileStatus, updateAgentPhoneNoStatus }, dispatchError] = useErrorContextValue()
  const [{ updateProfileData = {} }, updateProfileRequest] = useUpdateProfile()
  const [{ updateAgentPhoneNoData = {} }, updateAgentPhoneNoRequest] = useUpdateAgentPhoneNo()

  useImperativeHandle(parentRef, () => ({
    handleSaveUpdateDocs: (type) => {
      let body = {}
      switch (type) {
        case 'ktp':
          body = {
            ktp_no: that.current.ktp_no,
            documents: [{
              document_type: that.current.documents[0].document_type,
              document_uuid: that.current.documents[0].document_uuid
            }]
          }
          break
        case 'nib':
          body = {
            nib_no: that.current.nib_no,
            documents: [{
              document_type: that.current?.documents[0].document_type,
              document_uuid: that.current?.documents[0].document_uuid
            }]
          }
          break
        case 'npwp':
          body = {
            npwp_no: that.current.npwp_no,
            documents: [{
              document_type: that.current?.documents[0].document_type,
              document_uuid: that.current?.documents[0].document_uuid
            }]
          }
          break
        default:
      }
      updateProfileRequest(body)
    }
  }))

  const verifyDocumentRejection = useCallback((type) => {
    const { status, id } = agentDetails?.[`${type}_document`] || {}
    const errorText = {
      ktp: LANG_STRINGS.uploadNewKtpPhoto,
      npwp: LANG_STRINGS.uploadNewNpwpPhoto,
      nib: LANG_STRINGS.uploadNewNibPhoto,
    }
    if ((status === 'REJECTED') && that.current.documents[0]?.document_uuid === id) {
      ShowSnackbar.error({ text: errorText[type] })
      return false
    }
    return true
  }, [agentDetails])

  const handleSave = useCallback(() => {
    const updatedDetails = editProfileRef.current.validateFormValues()
    if (!updatedDetails) return
    switch (type) {
      case 'ktp':
      case 'npwp':
      case 'nib': {
        if ((!verifyDocumentRejection(type))) {
          // For Every Rejection, need to upload new FOTO
          return
        }
        setPopUpBeforeSubmit(true)
        return
      }
      case 'phone_no': {
        updateAgentPhoneNoRequest(formData)
        return
      }
      case 'name':
      case 'email':
      case 'corporate_pic_name':
      default: {
        updateProfileRequest(formData)
        return
      }
    }
  }, [
    formData, setPopUpBeforeSubmit, type,
    updateProfileRequest, verifyDocumentRejection, updateAgentPhoneNoRequest
  ])

  useEffect(() => {
    if (updateAgentPhoneNoStatus === 'success') {
      if (type === 'phone_no') {
        setToLocalStorage(PHONE_NUMBER_DATA, {
          new_phone_no: that.current.new_phone_no,
          operation_id: updateAgentPhoneNoData?.operation_id
        })
        history.push({ pathname: '/verify-otp' })
        resetError(['updateAgentPhoneNoStatus'])
      }
    } else if (updateAgentPhoneNoStatus) {
      ShowSnackbar.error({ text: updateAgentPhoneNoStatus })
      resetError(['updateAgentPhoneNoStatus'])
    }
    if (updateProfileStatus === 'success') {
      resetError(['updateProfileStatus'])
      setBottomSheetStatus(false)
      setUpdateNeeded(true)
    } else if (updateProfileStatus) {
      ShowSnackbar.error({ text: updateProfileStatus })
      resetError(['updateProfileStatus'])
    }
  }, [
    history, dispatchError, resetError, updateProfileStatus,
    type, updateProfileData?.operation_id, setBottomSheetStatus,
    setUpdateNeeded, updateAgentPhoneNoData?.operation_id, updateAgentPhoneNoStatus
  ])

  const handleDocumentFieldChange = useCallback((field, changedValue) => {
    that.current = {
      ...that.current,
      ...changedValue
    }
    if (that.current.documents[0]?.url && that.current[`${field}_no`]) {
      setBtnEnable(true)
    } else {
      setBtnEnable(false)
    }
  }, [])

  const handleTextFieldChange = useCallback((field, changedValue) => {
    that.current = {
      ...that.current,
      ...changedValue
    }
    setFormData({ [field]: that.current[`new_${field}`] })
    if (typeValid(field, that.current[`new_${field}`])) {
      setBtnEnable(true)
    } else {
      setBtnEnable(false)
    }
  }, [])

  const renderEditSection = useCallback(() => {
    switch (type) {
      case 'ktp':
        return (
          <EditProfileDetails
            ref={editProfileRef}
            heading={LANG_STRINGS.changeKTPNumber}
            form={getKTPDetailsForm(data, status)}
            onChange={(value) => handleDocumentFieldChange('ktp', value)}
          />
        )
      case 'nib':
        return (
          <EditProfileDetails
            ref={editProfileRef}
            heading={LANG_STRINGS.changeNIBNumber}
            form={getNIBDetailsForm(data, status)}
            onChange={(value) => handleDocumentFieldChange('nib', value)}
          />
        )
      case 'npwp':
        return (
          <EditProfileDetails
            ref={editProfileRef}
            heading={LANG_STRINGS.changeNPWPNumber}
            form={getNPWPDetailsForm(data, status)}
            onChange={(value) => handleDocumentFieldChange('npwp', value)}
          />
        )
      case 'name':
        return (
          <EditProfileDetails
            ref={editProfileRef}
            heading={LANG_STRINGS.changeFullName}
            form={getNameDetailsForm(data)}
            onChange={(value) => handleTextFieldChange('name', value)}
          />
        )
      case 'phone_no':
        return (
          <EditProfileDetails
            ref={editProfileRef}
            heading={LANG_STRINGS.changeMobileNumber}
            form={getPhoneNoDetailsForm(data)}
            onChange={(value) => handleTextFieldChange('phone_no', value)}
          />
        )
      case 'email':
        return (
          <EditProfileDetails
            ref={editProfileRef}
            heading={LANG_STRINGS.changeEmailAddress}
            form={getEmailDetailsForm(data)}
            onChange={(value) => handleTextFieldChange('email', value)}
          />
        )
        case 'corporate_pic_name':
          return (
            <EditProfileDetails
              ref={editProfileRef}
              heading={LANG_STRINGS.changeCorporatePicName}
              form={getCorporatePicNameDetailsForm(data)}
              onChange={(value) => handleTextFieldChange('corporate_pic_name', value)}
            />
          )
      default:
    }
  }, [type, data, status, handleDocumentFieldChange, handleTextFieldChange])

  return (
    <EditProfileFieldStyle>
      <CircularLoader isLoading={UPDATE_PROFILE_LOADER || UPDATE_AGENT_PHONE_NO_LOADER}>
        <div className='edit-container'>
          {renderEditSection()}
        </div>
        {status !== 'SUBMITTED' && (
          <Button onClick={handleSave} disabled={!btnEnable} className='submit-button'>
            {LANG_STRINGS.saveNew}
          </Button>
        )}
      </CircularLoader>
    </EditProfileFieldStyle>
  )
}

export default forwardRef(EditProfileFieldContainer)
