import React, { useCallback, useEffect, useRef, useState } from 'react'
import moment from 'moment'
import get from 'lodash/get'
import isEmpty from 'lodash/isEmpty'
import {
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { Container, Button, CustomText } from '../../../../../../components'
import ConfirmationModalV2 from '../../../../../../components/ConfirmationModalV2'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import StatusInfoCard from '../../../../../../components/StatusInfoCard'
import ToolTip from '../../../../../../components/ToolTip'
import { EDIT_ICON, CLOSE_GREY, GREEN_CHECK_V2 } from '../../../../../../images'
import { checkIsCorporateAgent } from '../../../../../../constants/appConstants'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../lang'
import { Row, DisplayFlexCCC, DisplayFlexRCSB } from '../../../../../../commonStyle/index.style'
import { VERIFICATION_LANG } from '../../../../VerifyKTPNPWP/lang'
import QuoteSection from '../../../../Policy/pages/MVQuoteReview/components/QuoteSections'
import {
  useAgentEmailVerification,
  useGetAgentDetails,
  useUpdateGlobal,
} from '../../../../../../state/globalState/hooks/useGlobalContext'
import {
  getFromLocalStorageData,
  removeFromLocalStorageData,
} from '../../../../../../helpers/localstorage'
import { OTP_END_TIME } from '../../../constants'
import EditProfileBottomSheet from '../../EditProfileBottomSheet'
import {
  PROFILE_FIELD_TYPE,
  getIndividualProfileFields,
  getCorporateProfileFields,
} from '../constants'
import { ProfileWrapper, KTPWarningWrapper } from './index.style'

function Profile(props) {
  const [{ getAgentDetailData }, getAgentDetailsRequest] = useGetAgentDetails()
  const [, agentEmailVerifcationRequest] = useAgentEmailVerification()
  const [{ getAgentDetailStatus, verifyAgentEmailStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [{ GET_AGENT_DETAIL_LOADER, GET_VERIFICATION_DOC_LOADER, VERIFY_AGENT_EMAIL_LOADER }] =
    useLoaderContextValue()

  const [showBottomSheet, setBottomSheetStatus] = useState(false)
  const [bottomSheetType, setBottomSheetType] = useState(null)
  const [editFieldStatus, setEditFieldStatus] = useState(null)
  const [showPopupBeforeSubmit, setPopUpBeforeSubmit] = useState(false)
  const [isVisibleKtpWarning, setKtpWarningStatus] = useState(true)
  const [isUpdateNeeded, setUpdateNeeded] = useState(false)

  const [{ isGojekDriver, isStaffAgent, agentDetails, isGuardianAgentLogin }, dispatchGlobal] =
    useUpdateGlobal()

  const phoneNoUpdatedAt = agentDetails?.phone_no_last_updated_at

  const childRef = useRef({})

  useEffect(() => {
    if (getFromLocalStorageData(OTP_END_TIME)) {
      removeFromLocalStorageData(OTP_END_TIME)
    }
  }, [])

  useEffect(() => {
    getAgentDetailsRequest()
  }, [getAgentDetailsRequest])

  useEffect(() => {
    if (getAgentDetailStatus === 'success') {
      dispatchGlobal({
        agentDetails: getAgentDetailData,
      })
    }

    if (verifyAgentEmailStatus === 'success') {
      ShowSnackbar.success({ text: VERIFICATION_LANG.sendEmailVerifyLink })
      resetError(['verifyAgentEmailStatus'])
    }
  }, [
    dispatchGlobal,
    getAgentDetailData,
    getAgentDetailStatus,
    verifyAgentEmailStatus,
    resetError,
  ])

  useEffect(() => {
    if (isUpdateNeeded) {
      getAgentDetailsRequest()
      setUpdateNeeded(false)
    }
  }, [isUpdateNeeded, getAgentDetailsRequest])

  const handleEmailVerification = () => {
    agentEmailVerifcationRequest()
  }

  const isValidForUpdate = (id) => {
    if (!phoneNoUpdatedAt) {
      return true
    }
    if (id === 'phone_no') {
      const previousDate = moment(phoneNoUpdatedAt)
      const currentDate = moment()
      return currentDate.diff(previousDate, 'days') > 180
    }
  }

  const isEditButtonDisable = (id) => {
    if (isGuardianAgentLogin || isStaffAgent) return true
    switch (id) {
      case 'phone_no':
        return !isValidForUpdate(id)
      case 'name':
        return agentDetails?.ktp_document?.status === 'SUBMITTED'
      default:
        return false
    }
  }

  const renderDetailRow = (id, text, title, isEditable, isValidate) => (
    <Row className="detail-item" align="center">
      <div className="row-header">
        <CustomText color={AgentColorPallette.fontDarkerGrey} size="0.8rem" className="row-title">
          {title}
          {id === 'phone_no' && phoneNoUpdatedAt && !isValidForUpdate(id) && (
            <ToolTip
              dataView={<CustomText>{LANG_STRINGS.canChangeNumberAfter6Months}</CustomText>}
              className="tooltip-view phone-number"
              wrapperClassName="tooltip-wrapper"
              hideTip
              hideCloseBtn
            >
              <Button
                backgroundColor={AgentColorPallette.darkBrown}
                color={AgentColorPallette.white}
                className="verified-btn"
              >
                {LANG_STRINGS.stored}
              </Button>
            </ToolTip>
          )}
        </CustomText>
        <div className="row-header-icon">
          {isValidate && <img src={GREEN_CHECK_V2} alt="validation-icon" />}
        </div>
      </div>
      <CustomText color={AgentColorPallette.black} size="0.8rem" className="row-text">
        {text}
      </CustomText>
      {isEditable && !isValidate && (
        <DisplayFlexCCC
          className={`edit-icon ${isEditButtonDisable(id) ? 'disabled' : ''}`}
          onClick={() => !isEditButtonDisable(id) && showUpdateProfileBottomSheet(id)}
        >
          {<img src={EDIT_ICON} alt="" />}
        </DisplayFlexCCC>
      )}
    </Row>
  )

  const handleBottomSheetType = (isOpen, bottomSheetType, editFieldStatus) => {
    setBottomSheetType(bottomSheetType)
    setBottomSheetStatus(isOpen)
    setEditFieldStatus(editFieldStatus)
  }

  const showUpdateProfileBottomSheet = (id, editFieldStatus = '') => {
    switch (id) {
      case 'ktp':
      case 'nib':
      case 'npwp':
        return handleBottomSheetType(true, id, editFieldStatus)
      case 'name':
      case 'phone_no':
      case 'email':
      case 'corporate_pic_name':
        return handleBottomSheetType(true, id)
      default:
    }
  }

  const renderActionButton = (id, text, editFieldStatus) => {
    if (!text) {
      return (
        <div
          className={`action-button ${isEditButtonDisable('KTP_NPWP') ? 'disabled' : ''}`}
          onClick={() =>
            !isEditButtonDisable('KTP_NPWP') &&
            showUpdateProfileBottomSheet(id)
          }
        >
          {id === 'ktp' && LANG_STRINGS.uploadKTP}
          {id === 'nib' && LANG_STRINGS.uploadNIB}
          {id === 'npwp' && LANG_STRINGS.uploadNPWP}
        </div>
      )
    } else {
      // handled unverified state
      switch (editFieldStatus) {
        case 'REJECTED':
          return (
            <div
              className={`action-button ${isEditButtonDisable('KTP_NPWP') ? 'disabled' : ''}`}
              onClick={() => !isEditButtonDisable('KTP_NPWP') && showUpdateProfileBottomSheet(id)}
            >
              {LANG_STRINGS.reUpload}
            </div>
          )
        case 'SUBMITTED':
          return (
            <div
              className={`action-button ${isEditButtonDisable('KTP_NPWP') ? 'disabled' : ''}`}
              onClick={() =>
                !isEditButtonDisable('KTP_NPWP') &&
                showUpdateProfileBottomSheet(id, editFieldStatus)
              }
            >
              {LANG_STRINGS.see}
            </div>
          )
        default:
      }
    }
  }

  const handleAgentAddress = () => {
    props.history.push('/agent-address')
  }

  const renderAddress = (text, title) => {
    return (
      <Row className="detail-item" align="center">
        <>
          <div className="row-header">
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              size="0.8rem"
              className="row-title"
            >
              {title}
            </CustomText>
          </div>
          <CustomText
            color={isEmpty(text) ? AgentColorPallette.fontGrey : AgentColorPallette.black}
            size="0.8rem"
            className="row-text"
          >
            {isEmpty(text) ? (
              <>
                {LANG_STRINGS.notCompletedShippingAddress}
                <div
                  className={`action-button ${isEditButtonDisable('address') ? 'disabled' : ''}`}
                  onClick={() => !isEditButtonDisable('address') && handleAgentAddress()}
                >
                  {LANG_STRINGS.addressContents}
                </div>
              </>
            ) : (
              text
            )}
          </CustomText>
          {!isEmpty(text) && (
            <DisplayFlexCCC
              className={`edit-icon ${isEditButtonDisable('address') ? 'disabled' : ''}`}
              onClick={() => !isEditButtonDisable('address') && handleAgentAddress()}
            >
              {<img src={EDIT_ICON} alt="" />}
            </DisplayFlexCCC>
          )}
        </>
      </Row>
    )
  }

  const renderEmail = (text, title, isValidate, isEditable) => {
    return (
      <Row className="detail-item" align="center">
        <>
          <div className="row-header">
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              size="0.8rem"
              className="row-title"
            >
              {title}
            </CustomText>
            <div className="row-header-icon">
              {isValidate && <img src={GREEN_CHECK_V2} alt="validation-icon" />}
            </div>
          </div>
          <CustomText
            color={isEmpty(text) ? AgentColorPallette.fontGrey : AgentColorPallette.black}
            size="0.8rem"
            className="row-text"
          >
            {text}
            {!isValidate && (
              <div
                className={`action-button ${isEditButtonDisable('email') ? 'disabled' : ''}`}
                onClick={() => !isEditButtonDisable('email') && handleEmailVerification()}
              >
                {LANG_STRINGS.verifyYourEmail.toUpperCase()}
              </div>
            )}
          </CustomText>
          {isEditable && (
            <DisplayFlexCCC
              className={`edit-icon ${isEditButtonDisable('email') ? 'disabled' : ''}`}
              onClick={() => !isEditButtonDisable('email') && showUpdateProfileBottomSheet('email')}
            >
              {<img src={EDIT_ICON} alt="" />}
            </DisplayFlexCCC>
          )}
        </>
      </Row>
    )
  }

  const renderRowWithStatus = (id, text, title, placeholder, isValidate, doc = {}) => {
    return (
      <Row className="detail-item" align="center">
        <>
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size="0.8rem"
            className="row-header row-status"
          >
            <div className="item">
              {title}{' '}
              {isValidate && (
                <img src={GREEN_CHECK_V2} alt="validation-icon" width="12px" height="12px" />
              )}
            </div>
            {doc.status === 'REJECTED' ? (
              <ToolTip
                dataView={<CustomText>{doc.reject_reason}</CustomText>}
                className="tooltip-view"
                wrapperClassName="tooltip-wrapper"
                hideTip
                hideCloseBtn
              >
                <Button
                  backgroundColor={AgentColorPallette.maroonRed}
                  color={AgentColorPallette.white}
                  className="verified-btn"
                >
                  {LANG_STRINGS.rejected}
                </Button>
              </ToolTip>
            ) : (
              doc.status === 'SUBMITTED' && (
                <Button
                  backgroundColor={AgentColorPallette.warning}
                  color={AgentColorPallette.white}
                  className="verified-btn"
                >
                  {LANG_STRINGS.isVerified}
                </Button>
              )
            )}
          </CustomText>
          <CustomText
            color={isEmpty(text) ? AgentColorPallette.fontGrey : AgentColorPallette.black}
            size="0.8rem"
            className="row-text"
          >
            {isEmpty(text) ? placeholder : text}
            {!isValidate && renderActionButton(id, text, doc.status)}
          </CustomText>
        </>
      </Row>
    )
  }

  const generateInfoMessage = (agentDetails, agentAddess) => {
    let message = LANG_STRINGS.please
    if (isEmpty(agentAddess)) {
      message += ' isi Alamat Pengiriman'
    }
    if (!agentDetails.is_email_verified) {
      message += `${message === LANG_STRINGS.please ? '' : ','} verifikasi Email anda`
    }
    if (!isCorporate && !agentDetails.is_ktp_verified) {
      message += ', lengkapi Nomor KTP'
    }
    if (isCorporate && !agentDetails.is_nib_verified) {
      message += ', lengkapi Nomor NIB'
    }
    if (!agentDetails.is_npwp_verified) {
      message += ', dan lengkapi Nomor NPWP'
    }

    return message === LANG_STRINGS.please ? '' : message
  }

  const getData = useCallback(
    (type) => {
      switch (type) {
        case 'name':
        case 'phone_no':
        case 'email':
        case 'corporate_pic_name':
          return agentDetails
        case 'ktp':
          return {
            ktp_no: agentDetails.ktp_no,
            documents: [
              {
                document_type: agentDetails?.ktp_document?.document_type,
                document_uuid: agentDetails?.ktp_document?.id,
                url: agentDetails?.ktp_document?.url,
              },
            ],
          }
        case 'nib':
          return {
            nib_no: agentDetails.nib_no,
            documents: [
              {
                document_type: agentDetails?.nib_document?.document_type,
                document_uuid: agentDetails?.nib_document?.id,
                url: agentDetails.nib_document?.url,
              },
            ],
          }
        case 'npwp':
          return {
            npwp_no: agentDetails.npwp_no,
            documents: [
              {
                document_type: agentDetails?.npwp_document?.document_type,
                document_uuid: agentDetails?.npwp_document?.id,
                url: agentDetails.npwp_document?.url,
              },
            ],
          }
        default:
      }
    },
    [agentDetails]
  )

  const handleModalOnClose = () => {
    setPopUpBeforeSubmit(false)
  }

  const handleModalOnOk = () => {
    childRef.current.handleSaveUpdateDocs(bottomSheetType)
    setPopUpBeforeSubmit(false)
  }

  const getDocumentRejectedMessage = () => {
    const ktpStatus = agentDetails?.ktp_document?.status === 'REJECTED'
    const nibStatus = agentDetails?.nib_document?.status === 'REJECTED'
    const npwpStatus = agentDetails?.npwp_document?.status === 'REJECTED'
    if (ktpStatus && npwpStatus) {
      return LANG_STRINGS.yourKTPRejectedGoToProfilePage('KTP dan NPWP')
    } else if (nibStatus && npwpStatus) {
      return LANG_STRINGS.yourKTPRejectedGoToProfilePage('NIB dan NPWP')
    } else if (ktpStatus) {
      return LANG_STRINGS.yourKTPRejectedGoToProfilePage('KTP')
    } else if (nibStatus) {
      return LANG_STRINGS.yourKTPRejectedGoToProfilePage('NIB')
    } else if (npwpStatus) {
      return LANG_STRINGS.yourKTPRejectedGoToProfilePage('NPWP')
    }
  }

  const isCorporate =  checkIsCorporateAgent(agentDetails?.agent_type)

  let agentAddress = get(agentDetails, 'address', {})
  if (!isEmpty(agentAddress)) {
    agentAddress = `${agentAddress.address} ${agentAddress.city_name} ${agentAddress.postal_code} ${agentAddress.province_name}`
  }

  const profileFields = isCorporate
    ? getCorporateProfileFields({
      agentDetails,
      agentAddress
    })
    : getIndividualProfileFields({
      agentDetails,
      agentAddress,
      isStaffAgent,
      isGojekDriver,
    })

  const renderProfileField = (field) => {
    switch (field.type) {
      case PROFILE_FIELD_TYPE.ADDRESS:
        return renderAddress(field.value, field.title)
      case PROFILE_FIELD_TYPE.EMAIL:
        return renderEmail(
          field.value,
          field.title,
          field.isValidate,
          field.isEditable
        )
      case PROFILE_FIELD_TYPE.ROW_WITH_STATUS:
        return renderRowWithStatus(
          field.id,
          field.value,
          field.title,
          field.placeholder,
          field.isValidate,
          field.doc
        )
      case PROFILE_FIELD_TYPE.DETAIL_ROW:
      default:
        return renderDetailRow(
          field.id,
          field.value,
          field.title,
          field.isEditable,
          field.isValidate
        )
    }
  }

  const isAnyDocumentRejected =
    agentDetails?.ktp_document?.status === 'REJECTED' ||
    agentDetails?.nib_document?.status === 'REJECTED' ||
    agentDetails?.npwp_document?.status === 'REJECTED'

  return (
    <Container
      title={LANG_STRINGS.myProfile}
      loader={VERIFY_AGENT_EMAIL_LOADER || GET_VERIFICATION_DOC_LOADER || GET_AGENT_DETAIL_LOADER}
      displayBackButton
      hideBottomTabs
    >
      {!isCorporate &&
        isVisibleKtpWarning &&
        isAnyDocumentRejected && (
          <KTPWarningWrapper>
            <DisplayFlexRCSB>
              <CustomText size="0.8rem" weight={700} color={AgentColorPallette.regular}>
                {getDocumentRejectedMessage()}
              </CustomText>
              <div className="close-icon" onClick={() => setKtpWarningStatus(false)}>
                <img src={CLOSE_GREY} alt="" />
              </div>
            </DisplayFlexRCSB>
          </KTPWarningWrapper>
        )}
      <ProfileWrapper isVisibleKtpWarning={!isCorporate && isVisibleKtpWarning && isAnyDocumentRejected}>
        {!isCorporate && generateInfoMessage(agentDetails, agentAddress) && (
          <StatusInfoCard
            info={generateInfoMessage(agentDetails, agentAddress)}
            isVisibleKtpWarning={isVisibleKtpWarning && isAnyDocumentRejected}
          />
        )}
        <QuoteSection title={LANG_STRINGS.dataProfile} />
        <div>
          {profileFields.map((field) => (
            <React.Fragment key={field.id}>
              {renderProfileField(field)}
            </React.Fragment>
          ))}
        </div>
      </ProfileWrapper>
      {showBottomSheet && (
        <EditProfileBottomSheet
          show={showBottomSheet}
          onClose={() => {
            setBottomSheetType(false, bottomSheetType)
            setBottomSheetStatus(false)
          }}
          type={bottomSheetType}
          setPopUpBeforeSubmit={setPopUpBeforeSubmit}
          setBottomSheetStatus={setBottomSheetStatus}
          setUpdateNeeded={setUpdateNeeded}
          status={editFieldStatus}
          data={getData(bottomSheetType)}
          agentDetails={agentDetails}
          ref={childRef}
        />
      )}
      {showPopupBeforeSubmit && (
        <ConfirmationModalV2
          okText={LANG_STRINGS.yesSimpan}
          cancelText={LANG_STRINGS.no.toUpperCase()}
          title={`${LANG_STRINGS.saveData} ${bottomSheetType.toUpperCase()}`}
          cancelButtonColor={AgentColorPallette.buddhaGold}
          okButtonColor={AgentColorPallette.buddhaGold}
          onCancel={handleModalOnClose}
          className="submit-confirmation"
          onOk={handleModalOnOk}
          visible
        >
          <CustomText size="0.8rem" color={AgentColorPallette.regular} bottom="1.5rem">
            {LANG_STRINGS.dataYouEnteredIsCorrect}
          </CustomText>
        </ConfirmationModalV2>
      )}
    </Container>
  )
}

export default Profile
