import { INFORMATION_NEW } from '../../images'
import { StatusInfoCardWrapper } from './index.style'

function StatusInfoCard ({ info, isVisibleKtpWarning, noIcon = false, bgColor, textWidth }) {
  return (
    <StatusInfoCardWrapper isVisibleKtpWarning bgColor={bgColor} textWidth={textWidth}>
      {
        !noIcon &&
          <div className='info-icon'>
            <img
              src={INFORMATION_NEW}
              alt='info-icon'
            />
          </div>
      }
      <div className='info-message'>
        {info}
      </div>
    </StatusInfoCardWrapper>
  )
}

export default StatusInfoCard
