import { DisplayFlexCCC, DisplayFlexRCC, Grid } from '../../../../../../../commonStyle/index.style'
import Heading from '../../../../../../../components/Heading'
import { MINI_EDIT_ICON } from '../../../../../../../images'
import { QuoteItem, QuoteSectionStyle, RenderMultipleImgSection } from './index.style'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { useCallback } from 'react'
import ZoomImg from '../../../../../../../components/zoomImg/index'
import { supportedVideoFormat } from '../../../../../../../constants/appConstants'

function QuoteSection ({
  isEdit, data = [], title, marginBtm,
  onEditClick = () => {}, children
}) {
  const renderMultipleImg = useCallback((images = []) => {
    return (
      <RenderMultipleImgSection
        count={images.length < 5 ? images.length : 5}
      >
        {
          images.map(img => (
            <ZoomImg
              src={img.url}
              imgClassName='multiple-img-box'
              key={img.filename}
              imgContainer={
                <DisplayFlexCCC className='multi-img-box'>
                  {
                    supportedVideoFormat.includes(img.url.split('.').pop()) ? (
                      <video className='multi-img'>
                        <source src={img.url} />
                      </video>
                    ) : (
                      <img className='multi-img' src={img.url} alt='' />
                    )
                  }
                </DisplayFlexCCC>
              }
            />
          ))
        }
      </RenderMultipleImgSection>
    )
  }, [])

  return (
    <QuoteSectionStyle marginBtm={marginBtm}>
      <Grid
        gridColumn={isEdit ? '6fr 1fr' : '1fr'}
        gridGap='1rem'
      >
        <Heading
          title={title}
          margin='0'
          size='1em'
        />
        {
          isEdit && (
            <div className='quote-edit' onClick={onEditClick}>
              <img src={MINI_EDIT_ICON} alt='edit' />&nbsp;
              {LANG_STRINGS.smallChange}
            </div>
          )
        }
      </Grid>
      {
        data.map((item, index) => {
          let value = ''
          if (Array.isArray(item.value) && item.value.length) {
            value = item.value
          } else if (!Array.isArray(item.value) && item.value) {
            value = item.value
          }
          if (item.value === 'mitraNotAvilable') return null
          if (item.type === 'img' && value) {
            return (
              <div className='quote-item'>
                <CustomText
                  size='0.9em'
                  color={AgentColorPallette.fontDarkerGrey}
                >
                  {item.title}
                </CustomText>
                {
                  item.isMultiple ? (
                    renderMultipleImg(item.value)
                  ) : (
                    <ZoomImg
                      src={item.value}
                      imgContainer={
                        <DisplayFlexRCC>
                          {
                            supportedVideoFormat.includes(item.value.split('.').pop()) ? (
                              <video className='photo-section'>
                                <source src={item.value} />
                              </video>
                            ) : (
                              <img src={item.value} className='photo-section' alt='' />
                            )
                          }
                        </DisplayFlexRCC>
                      }
                    />
                  )
                }
              </div>
            )
          }
          return (
            <QuoteItem
              key={item.title}
              gridColumn='1fr 2fr'
              gridGap='1rem'
              isBorderBtm={data.length !== (index + 1)}
            >
              <CustomText
                size='0.9em'
                color={AgentColorPallette.fontDarkerGrey}
              >
                {item.title}
              </CustomText>
              <CustomText
                size='0.9em'
                color={isEdit && !value ? AgentColorPallette.maroonRed : AgentColorPallette.darkCharcoal}
                textAlign='end'
              >
                {
                  (value) || (isEdit && item.type ? LANG_STRINGS.notUploadedYet : LANG_STRINGS.notFilledYet)
                }
              </CustomText>
            </QuoteItem>
          )
        })
      }
      {children}
    </QuoteSectionStyle>
  )
}

export default QuoteSection
